import numpy as np

def normalize(values):
    a = np.asarray(values, dtype=float)
    span = a.max() - a.min()
    if span == 0:
        return a - a.min()
    return (a - a.min()) / span

print(normalize([2, 4, 6]))

import pandas as pd

df = pd.DataFrame({"city": ["Oslo", "Bergen", "Oslo"]})

def city_counts(df):
    return df["city"].value_counts().to_dict()

print(city_counts(df))
